let modalOrder=document.querySelector(".modal-order"),btnModalPromo=document.querySelector(".promo__button"),btnModalAdvantages=document.querySelector(".advantages__button"),btnModalFooter=document.querySelector(".page-footer__order"),closeOrder=document.querySelector(".modal-order__close"),overlay=document.querySelector(".overlay"),removeShowTimeout;function modalButtons(){Object.values(arguments).forEach(e=>{e.addEventListener("click",function(e){e.preventDefault(),workModal(modalOrder,closeOrder,overlay)})})}function workModal(o,e,t){o.classList.remove("modal-hide"),o.classList.add("modal-show"),t.classList.add("overlay-show"),e.addEventListener("click",function(e){e.preventDefault(),hideModal(o,t)}),t.addEventListener("click",function(e){e.preventDefault(),hideModal(o,t)}),window.addEventListener("keydown",function(e){27===e.keyCode&&(e.preventDefault(),hideModal(o,t))})}function hideModal(e,o){clearTimeout(removeShowTimeout),e.classList.add("modal-hide"),o.classList.remove("overlay-show"),removeShowTimeout=setTimeout(function(){e.classList.remove("modal-show")},600)}modalButtons(btnModalPromo,btnModalAdvantages,btnModalFooter);